     */
    private static class ThrowingWriter extends Writer {
        @Override
        public void write(char[] cbuf, int off, int len) throws IOException {
            throw new IOException("Simulated IO Error");
        }

        @Override
        public void flush() throws IOException {}

        @Override
        public void close() throws IOException {}
    }















    @Test
    public void testTranslate_ComplexSurrogateHandling() throws IOException {
        // Testing the loop: for (int pt = 0; pt < consumed; pt++) { pos += Character.charCount(...) }
        // If translator returns 'consumed' count of codepoints, not chars.
        // The implementation logic: consumed is the number of codepoints handled.

        CharSequenceTranslator translator = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, Writer out) throws IOException {
                if (input.charAt(index) == '\uD83D') { // Start of emoji
                    out.write("EMOJI");
                    return 1; // Consumed 1 codepoint (which is 2 chars)
                }
                return 0;
            }
        };

        StringWriter writer = new StringWriter();
        // \uD83D\uDE00 is one codepoint
        translator.translate("\uD83D\uDE00", writer);
        assertEquals("EMOJI", writer.toString());
    }
}
